    try:
        with open(full_path, encoding="utf-8", errors="replace") as f:
            head = "".join(f.readline() for _ in range(generated_header.HEADER_LINES))
    except OSError as e:
        return error(f"{full_path} を読めない ({e})。生成したファイルかどうかを判定せずに、編集を実行させる")
